brief.key_terms_glossary:
[{'term': 'AER', 'definition': 'Annual Equivalent Rate; the interest rate that would be paid if interest was paid and compounded once a year.'}
 {'term': 'Representative APR', 'definition': 'The Annual Percentage Rate that the bank must be able to offer to at least 51% of successful applicants.'}
 {'term': 'LTV', 'definition': 'Loan to Value; the ratio of the mortgage loan amount to the appraised value of the property.'}
 {'term': 'Section 75', 'definition': 'A legal protection under the Consumer Credit Act making the card provider jointly liable for purchases between £100 and £30,000.'}]

