brief.key_terms_glossary:
[{'term': 'Mutual', 'definition': 'A financial institution owned by its members, who hold voting rights at the AGM, rather than by external shareholders.'}
 {'term': 'AER', 'definition': 'Annual Equivalent Rate, a standardised way of showing what the interest rate would be if interest was paid and compounded each year.'}
 {'term': 'LTV', 'definition': 'Loan-to-Value, the ratio between the mortgage loan amount and the total value of the property.'}
 {'term': 'Nominated Bank Account', 'definition': 'The external current account where Fernbridge sends funds, as we do not issue our own current accounts or cards.'}]

