brief.key_terms_glossary:
[{'term': 'AER', 'definition': 'Annual Equivalent Rate: The interest rate paid on savings, expressed as a yearly percentage.'}
 {'term': 'EAR', 'definition': 'Effective Annual Rate: The actual annual cost of an arranged overdraft, including the effect of compounding.'}
 {'term': 'Confirmation of Payee', 'definition': "A security service that verifies the recipient's name matches the account details before a Faster Payment is sent."}
 {'term': 'Authorised Push Payment (APP) Scam', 'definition': 'A fraud where a customer is tricked into voluntarily transferring money to an account controlled by a fraudster.'}
 {'term': 'Current Account Switch Service', 'definition': 'A regulated process that allows customers to move their banking to Quill within seven working days with a full guarantee.'}]

brief.product_positionings:
