brief.key_terms_glossary:
[{'term': 'ISA Transfer', 'definition': "The process of moving funds between providers to preserve the tax-free status of the '£20,000' annual allowance; funds must never be withdrawn and paid back in."}
 {'term': 'Capital at Risk', 'definition': 'The inherent risk that the value of an investment can decrease, meaning the investor may get back less than they originally invested.'}
 {'term': 'FSCS Protection', 'definition': "Protection provided by the Financial Services Compensation Scheme for up to '£85,000' per person per firm if the brokerage fails."}]

