brief.key_terms_glossary:
[{'term': 'Annual Allowance', 'definition': "The maximum amount that can be contributed to pensions each year while remaining eligible for tax relief, currently '£60,000'."}
 {'term': 'Money Purchase Annual Allowance (MPAA)', 'definition': "A reduced annual contribution limit of '£10,000' that applies once a member has flexibly accessed their pension."}
 {'term': 'Expression of Wish', 'definition': 'A non-binding statement detailing who the member would like to receive their pension benefits upon their death.'}
 {'term': 'Crystallisation', 'definition': 'The process of turning uncrystallised pension funds into a taxable income stream or a tax-free lump sum.'}]

