brief.key_terms_glossary:
[{'term': 'No Claims Discount (NCD)', 'definition': 'A reward for not claiming, which reduces the premium and can be protected for an additional cost.'}
 {'term': 'Excess', 'definition': 'The amount the policyholder pays toward a claim, which may be compulsory, voluntary, or specific to a risk like escape-of-water.'}
 {'term': 'Written in Trust', 'definition': 'A legal arrangement for life insurance where the policy is held by trustees to ensure the payout avoids probate and goes directly to beneficiaries.'}
 {'term': 'Cooling-off Period', 'definition': 'The statutory window—14 days for general insurance and 30 days for life insurance—during which a customer can cancel a policy.'}]
